  defaultWidth: 288,
};
RangeWithCalendar.argTypes = {
  ...sharedArgTypes,
  datePickerType: datePickerTypeArgType,
  defaultWidth: defaultWidthArgType,
};
RangeWithCalendar.parameters = sharedParameters;

